CREATE TYPE "CustomerJourneyState" AS ENUM ('new','engaged','product_interest','order_started','awaiting_customer_info','awaiting_confirmation','order_confirmed','order_submitted','post_order','completed','cancelled','human_support');
CREATE TYPE "CustomerActivityType" AS ENUM ('message_received','product_viewed','product_interest','product_selected','order_started','customer_info_provided','order_draft_created','order_confirmation_requested','order_confirmed','order_submitted','order_cancelled','order_completed','human_handover','conversation_closed');
CREATE TYPE "FollowUpType" AS ENUM ('order_confirmation_reminder','abandoned_order','customer_requested_followup','post_order','review_request','reorder');
CREATE TYPE "FollowUpStatus" AS ENUM ('pending','processing','sent','cancelled','failed','blocked','not_eligible');
ALTER TYPE "OrderConfirmationStatus" ADD VALUE IF NOT EXISTS 'not_requested';
ALTER TYPE "OrderStatus" ADD VALUE IF NOT EXISTS 'abandoned';
ALTER TYPE "OrderStatus" ADD VALUE IF NOT EXISTS 'expired';
ALTER TYPE "OrderStatus" ADD VALUE IF NOT EXISTS 'returned';
ALTER TABLE "customers" ADD COLUMN "journey_state" "CustomerJourneyState" NOT NULL DEFAULT 'new', ADD COLUMN "automation_opt_out" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "preferred_size" VARCHAR(50), ADD COLUMN "preferred_category" VARCHAR(100), ADD COLUMN "preferred_color" VARCHAR(100), ADD COLUMN "last_activity_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, ADD COLUMN "last_conversation_at" TIMESTAMP(3), ADD COLUMN "last_order_at" TIMESTAMP(3), ADD COLUMN "last_product_interest_at" TIMESTAMP(3);
CREATE TABLE "customer_activities" ("id" UUID NOT NULL, "customer_id" UUID NOT NULL, "conversation_id" UUID, "order_id" UUID, "type" "CustomerActivityType" NOT NULL, "summary" VARCHAR(500) NOT NULL, "metadata" JSONB, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "customer_activities_pkey" PRIMARY KEY ("id"));
CREATE TABLE "follow_ups" ("id" UUID NOT NULL, "customer_id" UUID NOT NULL, "conversation_id" UUID NOT NULL, "order_id" UUID, "type" "FollowUpType" NOT NULL, "scheduled_at" TIMESTAMP(3) NOT NULL, "status" "FollowUpStatus" NOT NULL DEFAULT 'pending', "payload" JSONB NOT NULL, "idempotency_key" VARCHAR(255) NOT NULL, "attempts" INTEGER NOT NULL DEFAULT 0, "sent_at" TIMESTAMP(3), "cancelled_at" TIMESTAMP(3), "failure_reason" VARCHAR(500), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "follow_ups_pkey" PRIMARY KEY ("id"));
CREATE TABLE "follow_up_templates" ("id" UUID NOT NULL, "name" VARCHAR(100) NOT NULL, "trigger" "FollowUpType" NOT NULL, "delay_minutes" INTEGER NOT NULL, "message" VARCHAR(2000) NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "follow_up_templates_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "follow_ups_idempotency_key_key" ON "follow_ups"("idempotency_key"); CREATE UNIQUE INDEX "follow_up_templates_trigger_key" ON "follow_up_templates"("trigger");
CREATE INDEX "customers_journey_state_last_activity_at_idx" ON "customers"("journey_state","last_activity_at"); CREATE INDEX "customer_activities_customer_id_created_at_idx" ON "customer_activities"("customer_id","created_at"); CREATE INDEX "customer_activities_conversation_id_created_at_idx" ON "customer_activities"("conversation_id","created_at"); CREATE INDEX "customer_activities_order_id_created_at_idx" ON "customer_activities"("order_id","created_at"); CREATE INDEX "follow_ups_status_scheduled_at_idx" ON "follow_ups"("status","scheduled_at"); CREATE INDEX "follow_ups_customer_id_created_at_idx" ON "follow_ups"("customer_id","created_at"); CREATE INDEX "follow_ups_conversation_id_status_idx" ON "follow_ups"("conversation_id","status");
ALTER TABLE "customer_activities" ADD CONSTRAINT "customer_activities_customer_id_fkey" FOREIGN KEY ("customer_id") REFERENCES "customers"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "customer_activities" ADD CONSTRAINT "customer_activities_conversation_id_fkey" FOREIGN KEY ("conversation_id") REFERENCES "conversations"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "customer_activities" ADD CONSTRAINT "customer_activities_order_id_fkey" FOREIGN KEY ("order_id") REFERENCES "orders"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "follow_ups" ADD CONSTRAINT "follow_ups_customer_id_fkey" FOREIGN KEY ("customer_id") REFERENCES "customers"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "follow_ups" ADD CONSTRAINT "follow_ups_conversation_id_fkey" FOREIGN KEY ("conversation_id") REFERENCES "conversations"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "follow_ups" ADD CONSTRAINT "follow_ups_order_id_fkey" FOREIGN KEY ("order_id") REFERENCES "orders"("id") ON DELETE SET NULL ON UPDATE CASCADE;
